unit.function:
function explodeNodeJS(p) {
  for (i = 1; i <= p; ++i) {
    var f = f * i;
    console.log(f * f * f * f * f);
    console.log('[!] explodeNodeJS invoked');
    console.log('Excuse me sir, is your CPU spiking?');
  }
}

