var http = require("http"),
    fs = require("fs"),
    p = require("path");

unit.expr_stmt:
DVNA.get('/', function(req, res){
  var filePath = p.join(__dirname, '/' + req.query.traverse);
  var readStream = fs.createReadStream(filePath);
  readStream.pipe(res);
});

